///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.setYYYYMM();
        scwin.ELW_MBR_INFO_TP_CD = 1;
        scwin.setTitle();
        $c.cm.PanelToGroupBox(panel_Top_1);
        scwin.setDataHeader();
        txb_basYm.hide();
        cmb_Bas_YYMM.hide();
        label_26.hide();
        rdo_RGHT_TP_CD.hide();
        txb_YYYYMM.hide();
        await scwin.basYYMMSync();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === 6) {
            //     발행가능 KOSPI200 기초자산
            txb_basYm.setValue("분기");
            cmb_Bas_YYMM.setSelectedIndex(1);
            cmb_Bas_YYMM.setValue($c.cp.valueOfIndex(cmb_Bas_YYMM, "VALUE", cmb_Bas_YYMM.getSelectedIndex()));
            txb_basYm.show("");
            cmb_Bas_YYMM.show("");
            label_26.hide();
            rdo_RGHT_TP_CD.hide();
            txb_YYYYMM.hide();
        } else if (nIndex === 3) {
            //    발행가능 스타지수 기초자산
            txb_basYm.setValue("기준년월");
            scwin.setYYYYMM();
            txb_basYm.show("");
            cmb_Bas_YYMM.hide();
            label_26.hide();
            rdo_RGHT_TP_CD.hide();
            txb_YYYYMM.show("");
        } else if (nIndex === 7) {
            //    발행가능 행사가격
            txb_basYm.setValue("기준년월");
            scwin.setYYYYMM();
            txb_basYm.show("");
            cmb_Bas_YYMM.hide();
            label_26.show("");
            rdo_RGHT_TP_CD.show("");
            txb_YYYYMM.show("");
        } else {
            txb_basYm.hide();
            cmb_Bas_YYMM.hide();
            label_26.hide();
            rdo_RGHT_TP_CD.hide();
            txb_YYYYMM.hide();
        }
        scwin.ELW_MBR_INFO_TP_CD = nIndex;
        scwin.setTitle();
        scwin.setDataHeader();
        await scwin.listSync();
        scwin.setTitle();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_List_1.getRowCount() > 0) {
            scwin.setValue(dts_List_1.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05950.dts_List_1_OnLoadCompleted" });
    }
};

