/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (scwin.ELW_MBR_INFO_TP_CD === 7) {
            if (rdo_RGHT_TP_CD.getValue() === "") {
                await $c.win.alert("권리형태를 지정해주세요.");
                rdo_RGHT_TP_CD.focus();
                return;
            }
            if (txb_YYYYMM.getValue() === "") {
                await $c.win.alert("기준년월을 지정해주세요.");
                txb_YYYYMM.focus();
                return;
            } else {
                if (txb_YYYYMM.getValue().length < 6) {
                    await $c.win.alert("올바른 날짜형식이 아닙니다.(YYYYMM)");
                    txb_YYYYMM.focus();
                    return;
                } else {
                    if (txb_YYYYMM.getValue().substr(0, 1) < 1) {
                        await $c.win.alert("올바른 날짜형식이 아닙니다.");
                        txb_YYYYMM.focus();
                        return;
                    }
                    if (txb_YYYYMM.getValue().substr(4, 2) > 12 || txb_YYYYMM.getValue().substr(4, 2) < 1) {
                        await $c.win.alert("올바른 날짜형식이 아닙니다.");
                        txb_YYYYMM.focus();
                        return;
                    }
                }
            }
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.btn_Search_onclick" });
    }
};

