/**
 * @method
 * @name txb_YYYYMM_onkeydown
 * @description txb_YYYYMM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_YYYYMM_onkeydown = async function() {
    try {
        if (!((window.event.keyCode >= 48 && window.event.keyCode <= 57) || window.event.keyCode === 8 || (window.event.keyCode >= 96 && window.event.keyCode <= 105) ||
                window.event.keyCode === 37 || window.event.keyCode === 39 || window.event.keyCode === 46 || window.event.keyCode === 9 || window.event.keyCode === 13)) {
            await $c.win.alert("숫자를 입력하세요.");
            return false;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.txb_YYYYMM_onkeydown" });
    }
};

