/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (scwin.ELW_MBR_INFO_TP_CD === 1) {
        arrPar[0] = txb_ISUR_CD_1.getValue(); // 발행기관코드값
        arrPar[1] = txb_COM_NM_1.getValue(); // 발행기관명

    } else if (scwin.ELW_MBR_INFO_TP_CD === 2) {
        arrPar[0] = txb_ISUR_CD_2.getValue(); // 발행기관코드값
        arrPar[1] = txb_COM_NM_2.getValue(); // 발행기관명

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        if (scwin.ELW_MBR_INFO_TP_CD === 1) {
            txb_ISUR_CD_1.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM_1.setValue(arrPar[0].COM_NM);
        } else if (scwin.ELW_MBR_INFO_TP_CD === 2) {
            txb_ISUR_CD_2.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM_2.setValue(arrPar[0].COM_NM);
        }
    }
};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setValue = function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.TR_JOB = "U";
