/**
 * @method
 * @name makeInfo
 * @description make Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeInfo = async function() {
    let contents = "";
    if (await scwin.checkForm()) {
        if (scwin.ELW_MBR_INFO_TP_CD === 2) {
            contents = txb_COM_NM_2.getValue() + " 종목이 " + $c.stf.FormatDateEx(edt_SDate_2.getValue()) + " 에 " + cmb_NotiTitle_2.getValue() + " 에서 편출될 예정이므로 \n" + "해당 종목을 기초자산으로 하는 주식워런트증권은 상장이 불가합니다.\n" + "자세한 사항은 상품상장팀 담당자에게 문의하여 주시기 바랍니다.";
            txa_NotiContn_2.setValue(contents);
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (scwin.ELW_MBR_INFO_TP_CD === 1) {
        if (txb_ISUR_CD_1.getValue() === "") {
            await $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_1.focus();
            return false;
        }
        if (edt_SDate_1.getValue() === "") {
            await $c.win.alert("[제한사유 발생시점]을 입력하세요.");
            edt_SDate_1.focus();
            return false;
        }
        if (edt_EDate_1.getValue() === "") {
            await $c.win.alert("[제한사유 종료시점]을 입력하세요.");
            edt_EDate_1.focus();
            return false;
        }
        if (txb_NotiTitle_1.getValue() === "") {
            await $c.win.alert("[제한사유]를 입력하세요.");
            txb_NotiTitle_1.focus();
            return false;
        }
        if (edt_SDate_1.getValue() > edt_EDate_1.getValue()) {
            await $c.win.alert("[제한사유 종료시점]을  이전으로 입력하세요.");
            edt_SDate_1.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD === 2) {
        if (txb_ISUR_CD_2.getValue() === "") {
            await $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_2.focus();
            return false;
        }
        if (edt_SDate_2.getValue() === "") {
            await $c.win.alert("[지수편출일]을 입력하세요.");
            edt_SDate_2.focus();
            return false;
        }
        if (cmb_NotiTitle_2.getValue() === "") {
            await $c.win.alert("[지수구분]을 선택하세요.");
            cmb_NotiTitle_2.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD === 3) {
        if (txb_ISUR_CD_1_1.getValue() === "") {
            await $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_1_1.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD === 4) {
        if (scwin.TR_JOB !== "D") {
            if (txb_NotiTitle_4.getValue() === "") {
                await $c.win.alert("[제목]을 입력하세요.");
                txb_NotiTitle_4.focus();
                return false;
            }
            if (txa_NotiContn_4.getValue() === "") {
                await $c.win.alert("[내용]을 입력하세요.");
                txa_NotiContn_4.focus();
                return false;
            } else {
                const vtxa_NotiContn_4 = txa_NotiContn_4.getValue();
                if ($c.stf.fn_chkXss(vtxa_NotiContn_4)) {
                    await $c.win.alert("허용되지 않는 문자가 들어가 있습니다.");
                    txa_NotiContn_4.focus();
                    return false;
                }
            }
            if (edt_SDate_4_1.getValue() === "") {
                await $c.win.alert("[메시지 표시기간]을 입력하세요.");
                edt_SDate_4_1.focus();
                return false;
            }
            if (edt_SDate_4_2.getValue() === "") {
                await $c.win.alert("[메시지 표시기간]을 입력하세요.");
                edt_SDate_4_2.focus();
                return false;
            }
            if (edt_SDate_4_1.getValue() > edt_SDate_4_2.getValue()) {
                await $c.win.alert("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.");
                edt_SDate_4_1.focus();
                return false;
            }
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD === 5) {
        if (txb_NotiTitle_5.getValue() === "") {
            await $c.win.alert("[제목]을 입력하세요.");
            txb_NotiTitle_5.focus();
            return false;
        }
        if (txa_NotiContn_5.getValue() === "") {
            await $c.win.alert("[내용]을 입력하세요.");
            txa_NotiContn_5.focus();
            return false;
        }
        if (edt_SDate_5_1.getValue() === "") {
            await $c.win.alert("[메시지 표시기간]을 입력하세요.");
            edt_SDate_5_1.focus();
            return false;
        }
        if (edt_SDate_5_2.getValue() === "") {
            await $c.win.alert("[메시지 표시기간]을 입력하세요.");
            edt_SDate_5_2.focus();
            return false;
        }
        if (edt_SDate_5_1.getValue() > edt_SDate_5_2.getValue()) {
            await $c.win.alert("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.");
            edt_SDate_5_1.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs = function() {
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB === "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB === "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB === "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    if (scwin.ELW_MBR_INFO_TP_CD === 1) {
        dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD_1.getValue());
        dts_Item.setCellData(1, "NOTI_TITLE", txb_NotiTitle_1.getValue());
        dts_Item.setCellData(1, "NOTI_CONTN", txa_NotiContn_1.getValue());
        dts_Item.setCellData(1, "STRT_DD", edt_SDate_1.getValue());
        dts_Item.setCellData(1, "END_DD", edt_EDate_1.getValue());
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwUlyChgInfo&SCREN_ID=" + "ULDSTF05950.xml" + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD === 2) {
        dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD_2.getValue());
        dts_Item.setCellData(1, "NOTI_TITLE", cmb_NotiTitle_2.getValue());
        dts_Item.setCellData(1, "NOTI_CONTN", txa_NotiContn_2.getValue());
        dts_Item.setCellData(1, "STRT_DD", edt_SDate_2.getValue());
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwUlyChgInfo&SCREN_ID=" + "ULDSTF05950.xml" + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD === 4) {
        dts_Item.setCellData(1, "NOTI_TITLE", txb_NotiTitle_4.getValue());
        dts_Item.setCellData(1, "NOTI_CONTN", txa_NotiContn_4.getValue());
        dts_Item.setCellData(1, "STRT_DD", edt_SDate_4_1.getValue());
        dts_Item.setCellData(1, "END_DD", edt_SDate_4_2.getValue());
        dts_Item.setCellData(1, "INFO_RND", txb_INFO_RND_4.getValue());
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", "3");
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwExchDeclInfo&SCREN_ID=" + "ULDSTF05950.xml" + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD === 5) {
        dts_Item.setCellData(1, "NOTI_TITLE", txb_NotiTitle_5.getValue());
        dts_Item.setCellData(1, "NOTI_CONTN", txa_NotiContn_5.getValue());
        dts_Item.setCellData(1, "STRT_DD", edt_SDate_5_1.getValue());
        dts_Item.setCellData(1, "END_DD", edt_SDate_5_2.getValue());
        dts_Item.setCellData(1, "INFO_RND", txb_INFO_RND_5.getValue());
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", "4");
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwExchDeclInfo&SCREN_ID=" + "ULDSTF05950.xml" + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    }
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";

    // alert(dts_Item.Text);
    trs_Save.Post();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", scwin.ELW_MBR_INFO_TP_CD);
        dts_Item.setCellData(1, "EMP_NO", js_id);
        scwin.trs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = "D";
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", scwin.ELW_MBR_INFO_TP_CD);
        scwin.trs();
    }
};
